create extension if not exists pgcrypto;
create type public.app_role as enum ('customer','artisan','admin','moderator');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text not null, phone text, locale text not null default 'ar', is_active boolean not null default true, created_at timestamptz not null default now());
create table public.user_roles (user_id uuid references public.profiles(id) on delete cascade, role public.app_role not null, primary key(user_id, role));
create table public.wilayas (id uuid primary key default gen_random_uuid(), code text unique not null check(code ~ '^[0-9]{2}$'), name_ar text not null, name_fr text not null, is_active boolean not null default true);
create table public.communes (id uuid primary key default gen_random_uuid(), code text not null, wilaya_id uuid not null references public.wilayas(id), name_ar text not null, name_fr text not null, is_active boolean not null default true, unique(wilaya_id, code));
create table public.categories (id uuid primary key default gen_random_uuid(), name_ar text not null, name_fr text not null, is_active boolean not null default true);
create table public.artisan_profiles (user_id uuid primary key references public.profiles(id) on delete cascade, category_id uuid references public.categories(id), bio text, verified_at timestamptz, is_available boolean not null default true);
create table public.artisan_services (id uuid primary key default gen_random_uuid(), artisan_id uuid not null references public.artisan_profiles(user_id), title text not null, description text, price_min numeric, price_max numeric, is_active boolean not null default true);
create table public.service_areas (artisan_id uuid references public.artisan_profiles(user_id) on delete cascade, commune_id uuid references public.communes(id), primary key(artisan_id, commune_id));
create table public.service_requests (id uuid primary key default gen_random_uuid(), customer_id uuid not null references public.profiles(id), artisan_id uuid references public.artisan_profiles(user_id), commune_id uuid references public.communes(id), description text not null, status text not null default 'pending', proposed_at timestamptz, created_at timestamptz not null default now());
create table public.reviews (id uuid primary key default gen_random_uuid(), request_id uuid unique references public.service_requests(id), customer_id uuid references public.profiles(id), artisan_id uuid references public.artisan_profiles(user_id), rating int not null check(rating between 1 and 5), body text, created_at timestamptz not null default now());
create table public.admin_audit_logs (id uuid primary key default gen_random_uuid(), actor_id uuid references auth.users(id), action text not null, entity text not null, entity_id uuid, metadata jsonb not null default '{}', created_at timestamptz not null default now());
create or replace function public.has_role(uid uuid, wanted public.app_role) returns boolean language sql stable security definer set search_path = public as $$ select exists(select 1 from public.user_roles where user_id=uid and role=wanted); $$;
alter table public.profiles enable row level security; alter table public.user_roles enable row level security; alter table public.wilayas enable row level security; alter table public.communes enable row level security; alter table public.categories enable row level security; alter table public.artisan_profiles enable row level security; alter table public.artisan_services enable row level security; alter table public.service_areas enable row level security; alter table public.service_requests enable row level security; alter table public.reviews enable row level security; alter table public.admin_audit_logs enable row level security;
create policy "active reference read" on public.wilayas for select using (is_active); create policy "active communes read" on public.communes for select using (is_active); create policy "active categories read" on public.categories for select using (is_active);
create policy "own profile" on public.profiles for select using (id=auth.uid()); create policy "own profile update" on public.profiles for update using (id=auth.uid()) with check (id=auth.uid());
create policy "artisan public read" on public.artisan_profiles for select using (true); create policy "artisan own update" on public.artisan_profiles for update using (user_id=auth.uid()) with check (user_id=auth.uid());
create policy "service public read" on public.artisan_services for select using (is_active); create policy "service artisan write" on public.artisan_services for all using (artisan_id=auth.uid()) with check (artisan_id=auth.uid());
create policy "request participants" on public.service_requests for select using (customer_id=auth.uid() or artisan_id=auth.uid()); create policy "customer request" on public.service_requests for insert with check (customer_id=auth.uid());
create policy "review participants" on public.reviews for select using (true); create policy "customer review" on public.reviews for insert with check (customer_id=auth.uid());
create policy "admin audit only" on public.admin_audit_logs for select using (public.has_role(auth.uid(),'admin') or public.has_role(auth.uid(),'moderator'));
